    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Error message */
.error-message {
    background: #f8d7da;
    color: #842029;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
}

/* Two-factor */
.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem 0;
}

.status-badge {
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.status-badge.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.disabled {
    background: #f8d7da;
    color: #842029;
}

.info-text {
    color: #6c757d;
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

.current-badge {
    font-size: 0.75rem;
    background: #e7f1ff;
    color: #0d6efd;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-weight: 500;
}

/* Sessions table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.6rem 0.75rem;
    background: #f8f9fa;
    border-bottom: 2px solid #e0e0e0;
    color: #495057;
    font-weight: 600;
}

.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e9ecef;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-item input[type="radio"] {
    accent-color: #0d6efd;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
