.preview-card p {
    margin: 0.5rem 0;
}

/* Theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #2a2a3e;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

