@page "/settings"
@rendermode InteractiveServer
@using sv_d0625ab81cbd4788998662b3bf8d2d7d.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">@ToastMessage</div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _savedProfile;
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";

    // Notifications
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<ChannelItem> Channels { get; set; } = new();

    // Security
    private SecuritySettings? _securitySettings;
    private bool ChangePasswordExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? PasswordError { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private string? RevokeSessionId { get; set; }
    private bool ShowRevokeConfirm { get; set; }

    // Appearance
    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        IsLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (ActiveSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                LoadProfileFields(profile);
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                NotifEmail = prefs.EmailNotifications;
                NotifPush = prefs.PushNotifications;
                NotifWeeklyDigest = prefs.WeeklyDigest;
                Channels = prefs.MutedChannels.Select(c => new ChannelItem(c, true)).ToList();
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                TwoFactorEnabled = _securitySettings.TwoFactorEnabled;
                ChangePasswordExpanded = false;
                CurrentPassword = "";
                NewPassword = "";
                ConfirmPassword = "";
                PasswordError = null;
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                Theme = appearance.Theme;
                FontSize = appearance.FontSize;
                Language = appearance.Language;
                CompactMode = appearance.CompactMode;
                break;
        }
        IsLoading = false;
    }

    private void LoadProfileFields(UserProfile profile)
    {
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileBio = profile.Bio;
        ProfileAvatarUrl = profile.AvatarUrl;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            LoadProfileFields(_savedProfile);
        }
    }

    // Notifications actions
    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest,
            Channels.Where(c => c.Muted).Select(c => c.Name).ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        PasswordError = null;
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "All password fields are required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }
        if (NewPassword.Length < 8)
        {
            PasswordError = "New password must be at least 8 characters.";
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ChangePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void PromptRevokeSession(string sessionId)
    {
        RevokeSessionId = sessionId;
        ShowRevokeConfirm = true;
    }

    private async Task ConfirmRevoke()
    {
        if (RevokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(RevokeSessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        ShowRevokeConfirm = false;
        RevokeSessionId = null;
        ShowToast("Session revoked.", "success");
    }

    private void CancelRevoke()
    {
        ShowRevokeConfirm = false;
        RevokeSessionId = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helper
    private async void ShowToast(string message, string type)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        ToastMessage = message;
        ToastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            ToastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // Render fragments
    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <div class="profile-layout">
                <div class="avatar-area">
                    <div class="avatar-preview">
                        <img src="@ProfileAvatarUrl" alt="Avatar" />
                    </div>
                    <label>Avatar URL</label>
                    <input type="text" @bind="ProfileAvatarUrl" placeholder="https://..." />
                </div>
                <div class="profile-fields">
                    <div class="field-group">
                        <label>Display Name</label>
                        <input type="text" @bind="ProfileDisplayName" />
                    </div>
                    <div class="field-group">
                        <label>Email</label>
                        <input type="email" @bind="ProfileEmail" />
                    </div>
                    <div class="field-group">
                        <label>Bio</label>
                        <textarea rows="4" @bind="ProfileBio"></textarea>
                    </div>
                </div>
            </div>
            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="NotifEmail" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="NotifPush" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="NotifWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @for (int i = 0; i < Channels.Count; i++)
                {
                    var idx = i;
                    <label class="channel-item">
                        <input type="checkbox" checked="@Channels[idx].Muted"
                               @onchange="(e) => Channels[idx] = Channels[idx] with { Muted = (bool)(e.Value ?? false) }" />
                        #@Channels[idx].Name
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        @if (PasswordError is not null)
                        {
                            <div class="error-message">@PasswordError</div>
                        }
                        <div class="field-group">
                            <label>Current Password</label>
                            <input type="password" @bind="CurrentPassword" />
                        </div>
                        <div class="field-group">
                            <label>New Password</label>
                            <input type="password" @bind="NewPassword" />
                        </div>
                        <div class="field-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="tfa-section">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="TwoFactorEnabled" />
                        <span class="toggle-switch"></span>
                        Two-Factor Authentication
                    </label>
                    <span class="status-badge @(TwoFactorEnabled ? "enabled" : "disabled")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <h3>Active Sessions</h3>
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings is not null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn-danger-sm" @onclick="() => PromptRevokeSession(session.Id)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (ShowRevokeConfirm)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="field-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t" checked="@(Theme == t)"
                                   @onchange="() => Theme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="field-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s" checked="@(FontSize == s)"
                                   @onchange="() => FontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="field-group">
                <label>Language</label>
                <select @bind="Language">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <input type="checkbox" @bind="CompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the current settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
                    <button class="btn-primary">Action Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} minutes ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{Theme.ToLower()}");
        classes.Add($"preview-font-{FontSize.ToLower()}");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private record ChannelItem(string Name, bool Muted);
}

