toolArgs.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: #555;
    font-weight: 500;
    transition: background 0.15s, color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #212529;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #495057;
}

/* Loading */
.loading {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 200px;
    color: #6c757d;
    font-size: 1.1rem;
}

/* Fields */
.field-group {
    margin-bottom: 1rem;
}

.field-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #495057;
    font-size: 0.9rem;
}

.field-group input[type="text"],
.field-group input[type="email"],
.field-group input[type="password"],
.field-group textarea,
.field-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.field-group input:focus,
.field-group textarea:focus,
.field-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

/* Profile layout */
.profile-layout {
    display: flex;
    gap: 2rem;
    margin-bottom: 1.5rem;
}

.avatar-area {
    flex-shrink: 0;
    width: 180px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #e0e0e0;
    margin-bottom: 0.75rem;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-area label {
    display: block;
    font-size: 0.85rem;
    font-weight: 500;
    color: #495057;
    margin-bottom: 0.25rem;
}

.avatar-area input {
    width: 100%;
    padding: 0.4rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.85rem;
}

.profile-fields {
    flex: 1;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #fff;
    color: #495057;
    border: 1px solid #ced4da;
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-secondary:hover {
    background: #f8f9fa;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-danger-sm {
    background: #dc3545;
    color: #fff;
    border: none;
    padding: 0.3rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #bb2d3b;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #333;
}

.toggle-label input[type="checkbox"] {
    width: 40px;
    height: 22px;
    appearance: none;
    background: #ccc;
    border-radius: 11px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
    flex-shrink: 0;
}

.toggle-label input[type="checkbox"]::after {
    content: "";
    position: absolute;
    width: 18px;
    height: 18px;
    background: #fff;
    border-radius: 50%;
    top: 2px;
    left: 2px;
    transition: transform 0.2s;
}

.toggle-label input[type="checkbox"]:checked {
    background: #0d6efd;
}

.toggle-label input[type="checkbox"]:checked::after {
    transform: translateX(18px);
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.5rem 0;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
    color: #495057;
    cursor: pointer;
}

.channel-item input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #0d6efd;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Error message */
.error-message {
    background: #f8d7da;
    color: #842029;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
}

/* Two-factor */
.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem 0;
}

.status-badge {
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.status-badge.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.disabled {
    background: #f8d7da;
    color: #842029;
}

.info-text {
    color: #6c757d;
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

.current-badge {
    font-size: 0.75rem;
    background: #e7f1ff;
    color: #0d6efd;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-weight: 500;
}

/* Sessions table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.6rem 0.75rem;
    background: #f8f9fa;
    border-bottom: 2px solid #e0e0e0;
    color: #495057;
    font-weight: 600;
}

.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e9ecef;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-item input[type="radio"] {
    accent-color: #0d6efd;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal-dialog p {
    color: #495057;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    color: #fff;
    font-size: 0.9rem;
    font-weight: 500;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
    z-index: 2000;
    animation: toast-in 0.3s ease;
}

.toast.success {
    background: #198754;
}

.toast.error {
    background: #dc3545;
}

@@keyframes toast-in {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Appearance preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.2s;
}

.preview-area h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

.preview-card p {
    margin: 0.5rem 0;
}

/* Theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #2a2a3e;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

